        let name_given = || served.aws.asked.lock().unwrap().iter().filter(|a| a["url"].as_str().is_some_and(|u| u.ends_with("/DictUpdate"))).count();
        if given { until("named", || name_given() >= 2) } else { assert_eq!(name_given(), 1, "{named}") }
