    let mut second = superci_testkit::github::GitHub::app();
    second["id"] = 2002.into(); second["owner"] = "globex".into(); second["slug"] = "superci-globex".into();
    served.aws.put(&format!("/superci/{PLANE}/GITHUB_APP_2002"), &second.to_string());
