/// The sweep, with a machine whose job was seen to begin though it is kept as launched (two writes crossed): left to
/// run. A machine that never began the job whose runner took its own (GitHub has that one queued still), late a
/// third time: ended and failed here, and nothing failed at GitHub (its own job ran on another's machine), as one late
/// for its own job is failed there too.
#[test]
fn the_sweep_leaves_a_launched_job_seen_to_begin_and_fails_a_third_late_machine_of_another_jobs_only_here() {
    let served = serve(|_| {});
    served.connect_github();
    let now = served.now_ms();
    let (queued, _) = served.github.queue("queued still", "superci", now);
    let (own, _) = served.github.queue("its own queued still", "superci", now);
    {
        let mut m = served.store.0.lock().unwrap();
        let job = |id: u64, seen: bool| serde_json::json!({ "job_id": id, "run_id": 41, "repo": "acme/app", "state": "launched", "label": "superci", "cloud": "cloudflare", "at_ms": now - 600_000, "launched_ms": now - 600_000,
            "installation_id": 42, "runner": format!("superci-{id}"), "runner_id": id, "machine_id": format!("machine-{id}"), "seen_in_progress": seen, "began": seen });
        m.insert("job:401".into(), job(401, true).to_string());
        let mut other = job(402, false);
        (other["for_job"], other["retries"]) = (queued.into(), 2.into());
        m.insert("job:402".into(), other.to_string());
        // (One late a third time for its own job, which GitHub has queued still: failed there too.)
        let mut alone = job(own, false);
        alone["retries"] = 2.into();
        m.insert(format!("job:{own}"), alone.to_string());
    }
    served.upkeep();
    let record = |id: u64| served.store.under(&format!("job:{id}"))[0].1.clone();
    for id in [402, own] { assert!(record(id)["state"] == "failed" && record(id)["error"].as_str().is_some_and(|e| e.contains("did not start a machine for it, three times")), "{}", record(id)) }
    assert_eq!(served.github.asked.lock().unwrap().iter().filter(|a| a.contains("generate-jitconfig")).count(), 1, "a failing runner for its own job only");
    assert!(record(401)["state"] == "launched" && record(401)["error"].is_null(), "{}", record(401));
}

/// GitLab jobs on AWS whose runner settings a machine's start-up script cannot carry safely (a GitLab address with a
/// user in it, a runner token GitLab gave with a character a shell reads) start no machine, saying why; and a GitLab
/// pipeline's number is no run to cancel.
#[test]
fn gitlab_jobs_whose_runner_settings_a_start_up_script_cannot_carry_say_so_and_a_pipeline_is_no_run_to_cancel() {
    let served = aws_plane("");
    let mut odd = superci_testkit::GitLab::connection();
    odd["url"] = "https://acme@gitlab.com".into();
    served.aws.put(&format!("/superci/{PLANE}/GITLAB"), &odd.to_string());
    served.store.0.lock().unwrap().insert("aws:no-fleet".into(), served.now_ms().to_string());
    let job = |name: &str| { let (id, pending) = served.gitlab.pending(name, &["superci"], served.now_ms()); assert_eq!(served.gitlab_webhook(pending), 200); served.store.under(&format!("job:gl{id}"))[0].1.clone() };
    let j = job("odd address");
    assert!(j["error"].as_str().is_some_and(|e| e.contains("invalid GitLab runner settings")) && j["machine_id"].is_null(), "{j}");
    served.connect_gitlab();
    served.gitlab.runner_tokens_end_with("+x");
    let j = job("odd token");
    assert!(j["error"].as_str().is_some_and(|e| e.contains("invalid GitLab runner settings")) && j["machine_id"].is_null(), "{j}");
    let pipeline = j["run_id"].as_u64().unwrap();
    let status = ureq::post(&format!("{}/runs/{pipeline}/cancel", served.url)).header("authorization", &format!("Bearer {}", served.key)).config().http_status_as_error(false).build().send_empty().unwrap().status().as_u16();
    assert_eq!(status, 404);
}

/// AWS machines and the cache: a GitLab job's, on an Ubuntu whose Docker keeps images, gets the cache but not the
/// layer store (its runner starts Docker itself); a job whose machine's cache link the store will not keep starts
/// without the cache.
#[test]
fn a_gitlab_jobs_machine_gets_the_cache_without_the_layer_store_and_one_whose_cache_link_is_not_kept_none() {
    let served = aws_plane("");
    served.connect_gitlab();
    served.aws.fail("RunInstances", 200, &aws_started(), None);
    served.store.0.lock().unwrap().insert("aws:no-fleet".into(), served.now_ms().to_string());
    let bucket = superci_core::cache::bucket(PLANE, "us-east-1");
    served.github.put_object(&format!("{bucket}/{}", superci_core::cache::program_key("x86_64")), b"program");
    served.github.put_object(&format!("{bucket}/{}", superci_core::cache::layers_key("x86_64")), b"program");
    let script = || {
        let asked = served.aws.asked.lock().unwrap().iter().rev().find(|a| a["asked"].as_str().unwrap_or_default().contains("Action=RunInstances")).map(|a| a["asked"].as_str().unwrap().to_string()).expect("a machine asked for");
        let data: String = url::form_urlencoded::parse(asked.as_bytes()).find(|(k, _)| k == "UserData").map(|(_, v)| v.to_string()).unwrap();
        use base64::Engine;
        String::from_utf8_lossy(&base64::engine::general_purpose::STANDARD.decode(data).unwrap()).to_string()
    };
    let (gid, pending) = served.gitlab.pending("images", &["superci/image=ubuntu26"], served.now_ms());
    assert_eq!(served.gitlab_webhook(pending), 200);
    let j = served.store.under(&format!("job:gl{gid}"))[0].1.clone();
    assert!(j["state"] == "launched" && j["keeps"] != true && j["layers"] != true && script().contains("plane.acme.test/cache/"), "{j}");
    // (A GitHub job's, of the same label, keeps its images.)
    let g = aws_job(&served, "images", "superci/image=ubuntu26");
    assert!(g["keeps"] == true, "{g}");
    served.store_refuses(Some("cachem:"));
    let j = aws_job(&served, "no link", "superci/image=ubuntu26");
    served.store_refuses(None);
    assert!(j["state"] == "launched" && !script().contains("plane.acme.test/cache/"), "{j}");
}

/// A region's network made by SuperCI, found once made to be the only one of its own there (none made at once
/// elsewhere): kept, nothing deleted.
#[test]
fn a_regions_network_made_and_found_alone_once_made_is_kept() {
    let served = serve(|c| {
        (c.aws_own, c.aws_own_creds) = (Some(("111111111111".into(), "us-east-1".into())), Some(superci_core::aws::Credentials { access_key_id: "ASIAX".into(), secret_access_key: "secret".into(), session_token: Some("tok".into()), expires_at_ms: u64::MAX }));
    });
    let home = signed_in(&served);
    let ec2 = |action: &str, inside: &str| format!("<{action}Response xmlns=\"http://ec2.amazonaws.com/doc/2016-11-15/\"><requestId>1</requestId>{inside}</{action}Response>");
    served.aws.replaying(include_str!("../fixtures/aws/regions/add.jsonl"), &[("mixplane0001", PLANE)]);
    for (action, answer, times) in [("DescribeVpcs|ec2.eu-north-1|tag%3Asuperci", ec2("DescribeVpcs", "<vpcSet/>"), 2), ("CreateVpc", ec2("CreateVpc", "<vpc><vpcId>vpc-00000000000000002</vpcId></vpc>"), 1),
        ("DescribeVpcs|ec2.eu-north-1|tag%3Asuperci", ec2("DescribeVpcs", "<vpcSet><item><vpcId>vpc-00000000000000002</vpcId></item></vpcSet>"), 1)] {
        served.aws.fail(action, 200, &answer, Some(times));
    }
    let (ok, said) = superci_in_time(&home, &["runners", "update", "aws", "--regions=us-east-1,eu-north-1"], 90);
    assert!(ok, "{said}");
    assert!(served.aws.settings(PLANE).iter().any(|(k, v)| k == "AWS_REGIONS" && v.contains("eu-north-1")), "added");
    assert!(!served.aws.asked.lock().unwrap().iter().any(|a| a["asked"].as_str().unwrap_or_default().contains("Action=DeleteVpc&")), "nothing deleted");
    let _ = std::fs::remove_dir_all(&home);
}

/// A region's network deleted while a machine of the control plane is still listed there once it was ended: asked
/// again a moment on, and the network deleted once AWS lists none.
#[test]
fn a_regions_network_is_deleted_once_aws_no_longer_lists_the_machines_it_ended() {
    let served = serve(|c| {
        (c.aws_own, c.aws_own_creds) = (Some(("111111111111".into(), "us-east-1".into())), Some(superci_core::aws::Credentials { access_key_id: "ASIAX".into(), secret_access_key: "secret".into(), session_token: Some("tok".into()), expires_at_ms: u64::MAX }));
    });
    let home = signed_in(&served);
    let ec2 = |action: &str, inside: &str| format!("<{action}Response xmlns=\"http://ec2.amazonaws.com/doc/2016-11-15/\"><requestId>1</requestId>{inside}</{action}Response>");
    let gone = |url: &str| serde_json::json!({ "method": "DELETE", "url": url, "target": "", "asked": "", "status": 404, "answer": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<Error><Code>NoSuchKey</Code><Message>The specified key does not exist.</Message></Error>" }).to_string();
    let bucket = format!("https://superci-plane-{PLANE}-eu-north-1.s3.eu-north-1.amazonaws.com/");
    served.aws.replaying(include_str!("../fixtures/aws/regions/delete.jsonl"), &[("mixplane0001", PLANE)]);
    served.aws.replaying(&[gone(&bucket), gone(&format!("{bucket}superci/cache-0.19.16-aarch64"))].join("\n"), &[]);
    let up = ec2("DescribeInstances", "<reservationSet><item><instancesSet><item><instanceId>i-0aaaaaaaaaaaaaaaa</instanceId></item></instancesSet></item></reservationSet>");
    served.aws.fail("DescribeInstances|tag%3Asuperci-plane", 200, &up, Some(2));
    served.aws.fail("TerminateInstances", 200, &ec2("TerminateInstances", "<instancesSet><item><instanceId>i-0aaaaaaaaaaaaaaaa</instanceId></item></instancesSet>"), Some(1));
    let (ok, said) = superci_in_time(&home, &["debug", "networks", "eu-north-1"], 90);
    assert!(ok && said.contains("deleted in eu-north-1"), "{said}");
    let asked = |what: &str| served.aws.asked.lock().unwrap().iter().filter(|a| a["asked"].as_str().unwrap_or_default().contains(what)).count();
    assert!(asked("Action=TerminateInstances") == 1 && asked("Filter.1.Name=tag%3Asuperci-plane&Filter.1.Value.1=testplane0001&Filter.2.Name=instance-state-name") == 3 && asked("Action=DeleteVpc&") == 1);
    let _ = std::fs::remove_dir_all(&home);
}

/// A run from a computer whose later job waits for room past the day its run's records are kept: once there is room,
/// no machine is started for a job there is nothing left of for its runner to take; the job fails saying so.
#[test]
fn a_run_from_a_computers_job_still_waiting_when_its_runs_records_go_gets_no_machine_and_fails_saying_why() {
    let served = serve(|_| {});
    let wf = "jobs:\n  a:\n    runs-on: superci\n    steps:\n      - run: echo a\n  b:\n    needs: a\n    runs-on: superci\n    steps:\n      - run: echo b\n";
    let body = serde_json::json!({ "workflow": wf, "path": ".github/workflows/ci.yml", "repository": "acme/app", "ref": "refs/heads/main" });
    let mut r = ureq::post(&format!("{}/runs", served.url)).header("authorization", &format!("Bearer {}", served.run_key)).send(body.to_string()).unwrap();
    let said: serde_json::Value = r.body_mut().read_json().unwrap();
    let run = said["run_id"].as_str().unwrap_or_else(|| panic!("{said}")).to_string();
    let a = superci_testkit::Runner::of_job(&served, &run, "a").expect("a's runner");
    assert_eq!(a.take(), 200);
    // a ends most of a day on; b finds no room for its machine, and waits.
    served.later(20 * 3_600_000);
    served.machines_refuse(Some("no room"));
    assert_eq!(a.finish("succeeded"), 200);
    let b = || served.store.under("job:").into_iter().map(|(_, j)| j).find(|j| j["name"] == "b").expect("b's job");
    assert!(b()["state"] == "waiting", "{}", b());
    // The run's day is over: what it kept goes, b still waiting.
    served.later(5 * 3_600_000);
    served.upkeep();
    assert!(served.store.under(&format!("run:{run}")).is_empty() && served.store.under("rjob:").is_empty() && b()["state"] == "waiting", "{}", b());
    // Room again: no machine for b.
    served.machines_refuse(None);
    let machines = served.machines.0.lock().unwrap().len();
    served.upkeep();
    assert!(b()["state"] == "failed" && b()["error"].as_str().unwrap_or_default().contains("kept a day") && served.machines.0.lock().unwrap().len() == machines, "{}", b());
}

/// A layer the store has that is not public, proposed again by a machine of a repository it is granted to already:
/// the store has it, no upload asked for.
#[test]
fn a_private_layer_proposed_again_by_a_repository_granted_it_is_had_already() {
    let (served, link, id) = layers_machine(true);
    let ns = format!("gh{}", served.store.under(&format!("job:{id}"))[0].1["repo_id"].as_u64().expect("its repository's id"));
    let (digest, now) = (format!("sha256:{}", "7".repeat(64)), served.now_ms());
    {
        let mut m = served.store.0.lock().unwrap();
        let hex = "7".repeat(64);
        m.insert(format!("layer:us-east-1:{digest}"), serde_json::json!({ "size": 100, "diff_id": "", "erofs": { "key": format!("layers/{hex}.erofs"), "size": 1 }, "blob": { "key": format!("layers/{hex}.blob"), "size": 100 }, "made": now, "used": now }).to_string());
        m.insert(format!("lgrant:{ns}:{digest}"), now.to_string());
    }
    let mut r = ureq::post(&format!("{}/cache/{link}/layers-propose", served.url)).send(serde_json::json!({ "layers": [{ "digest": digest, "size": 100 }] }).to_string()).unwrap();
    let said: serde_json::Value = r.body_mut().read_json().unwrap();
    assert_eq!(said["layers"][&digest]["do"], "have", "{said}");
}

/// A workspace signed in to Cloudflare alone, or Modal alone, whose cloud refuses the sign-in as the dashboard looks
/// there: its control plane and key are kept beside the sign-in noted as ended (they still read the control plane).
#[test]
fn a_workspace_whose_only_sign_in_is_refused_keeps_its_control_plane_noting_the_sign_in_as_ended() {
    let served = serve(|_| {});
    let cf = serde_json::json!({ "access": "example-access_token-ended", "expires_at_ms": 4102444800000u64, "refresh": "example-refresh_token-ended" });
    let modal = serde_json::json!({ "token_id": "ak-superciendedrecording00", "token_secret": "as-superciendedrecording00", "workspace": "acmeci" });
    for (cloud, sign_in, recording, ended) in [("cloudflare", cf, include_str!("../fixtures/cloudflare/sign-in/ended.jsonl"), "cloudflare_ended"),
        ("modal", modal, include_str!("../fixtures/modal/sign-in/ended.jsonl"), "modal_ended")] {
        let home = home(&served);
        let file = home.join("workspaces/default/sign-ins.json");
        let mut kept: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(&file).unwrap()).unwrap();
        kept[cloud] = sign_in;
        std::fs::write(&file, kept.to_string()).unwrap();
        std::fs::write(home.join("aws-at"), &served.aws.url).unwrap();
        served.aws.replaying(recording, &[]);
        let (_child, link) = dashboard(&home);
        let now = || serde_json::from_str::<serde_json::Value>(&std::fs::read_to_string(&file).unwrap_or_default()).unwrap_or_default();
        until("the sign-in noted as ended", || { common::part(&link, "/?p=planes&fragment=1"); now()[ended] == true });
        let now = now();
        assert!(now[cloud].is_null() && now["plane"]["Aws"]["plane_id"] == "testplane0001" && now["key"]["value"] == served.key.as_str(), "{cloud}: {now}");
        let _ = std::fs::remove_dir_all(&home);
    }
}

/// A run from a computer moved on by a control plane whose store keeps records' ends beside them, while another
/// request writes the run: written again over what is there then, what the other wrote kept.
#[test]
fn a_run_written_meanwhile_in_a_store_that_keeps_ends_is_moved_on_over_what_is_there_then() {
    let served = superci_testkit::serve_with_ends(|_| {});
    served.written_meanwhile("run:", 1, |v| v.map(|v| { let mut r: serde_json::Value = serde_json::from_str(v).unwrap(); r["meanwhile"] = true.into(); r.to_string() }));
    let body = serde_json::json!({ "workflow": "jobs:\n  a:\n    runs-on: superci\n    steps:\n      - run: echo a\n", "path": ".github/workflows/ci.yml", "repository": "acme/app", "ref": "refs/heads/main" });
    let mut r = ureq::post(&format!("{}/runs", served.url)).header("authorization", &format!("Bearer {}", served.run_key)).send(body.to_string()).unwrap();
    let said: serde_json::Value = r.body_mut().read_json().unwrap();
    let run = said["run_id"].as_str().unwrap_or_else(|| panic!("{said}")).to_string();
    let record = served.store.under(&format!("run:{run}"))[0].1.clone();
    assert!(record["meanwhile"] == true && record["jobs"][0]["state"] == "started" && served.store.under("job:").len() == 1, "{record}");
}

/// A run from a computer whose job's record the store refused as the job started (its runner's message kept),
/// cancelled: the job ends with the run, with no record of it to end.
#[test]
fn a_run_whose_jobs_record_the_store_refused_is_cancelled_all_the_same() {
    let served = serve(|_| {});
    served.store_refuses(Some("job:"));
    let body = serde_json::json!({ "workflow": "jobs:\n  a:\n    runs-on: superci\n    steps:\n      - run: echo a\n", "path": ".github/workflows/ci.yml", "repository": "acme/app", "ref": "refs/heads/main" });
    let r = ureq::post(&format!("{}/runs", served.url)).header("authorization", &format!("Bearer {}", served.run_key)).config().http_status_as_error(false).build().send(body.to_string()).unwrap();
    assert_eq!(r.status().as_u16(), 400);
    served.store_refuses(None);
    // Refused with nothing under way: nothing of it kept, for the upkeep to start later.
    assert!(served.store.under("run:").is_empty() && served.store.under("job:").is_empty() && served.store.under("rjob:").is_empty(), "{:?}", served.store.under("run:"));
    // One whose job's record went all the same (as a start whose undoing failed too leaves it): cancelled.
    let mut r = ureq::post(&format!("{}/runs", served.url)).header("authorization", &format!("Bearer {}", served.run_key)).send(body.to_string()).unwrap();
    let run = r.body_mut().read_json::<serde_json::Value>().unwrap()["run_id"].as_str().unwrap().to_string();
    served.store.0.lock().unwrap().retain(|k, _| !k.starts_with("job:"));
    let record = served.store.under(&format!("run:{run}"))[0].1.clone();
    assert!(record["jobs"][0]["state"] == "started" && served.store.under("rjob:").len() == 1, "{record}");
    let run = run.as_str();
    let mut r = ureq::post(&format!("{}/runs/{run}/cancel", served.url)).header("authorization", &format!("Bearer {}", served.key)).send_empty().unwrap();
    let said: serde_json::Value = r.body_mut().read_json().unwrap();
    assert!(said["cancelled"] == true && served.store.under("rjob:")[0].1["result"] == "cancelled" && served.store.under("job:").is_empty(), "{said}");
}

#[test]
fn jobs_the_sweep_ends_over_hours_and_days_are_said_on_their_pages_as_it_ended_them() {
    let Some(mut b) = Browser::open(1300, 900) else { eprintln!("no Chrome here: skipped"); return };
    // One whose machine never takes it, one that runs and never ends, one that ended; then hours and days pass.
    let served = serve(|_| {});
    served.connect_github();
    let (_, q) = served.github.queue("never-taken", "superci", served.now_ms()); served.webhook(q);
    let (b2, q) = served.github.queue("never-ends", "superci", served.now_ms()); served.webhook(q); served.webhook(served.github.start(b2));
    let (c, q) = served.github.queue("ended", "superci", served.now_ms()); served.webhook(q); served.webhook(served.github.start(c)); served.webhook(served.github.finish(c, "success", "ok", served.now_ms()));
    for ms in [11 * 60_000, 6 * 3_600_000, 25 * 3_600_000, 3 * 86_400_000] { served.later(ms); served.upkeep(); }
    let home = home(&served);
    let (mut child, link) = dashboard(&home);
    b.goto(&link);
    b.wait(&shows("Usage"));
    b.click("nav a", "Runs");
    b.click(".tabs a", "Jobs");
    // Past its longest time; never started, three times: each said; the one that ended as it ended.
    b.wait(&format!("{} && {} && {}", reads("ran past its longest time (6 hours)"), reads("did not start a machine for it, three times"), reads("ended")));
    // Their tests from the CLI: the swept one's too, though no code host said it failed.
    for id in [b2, c] {
        let o = common::command(&home).args(["jobs", "retrieve", &id.to_string(), "--tests"]).output().unwrap();
        assert!(o.status.code().is_some_and(|c| c <= 3) && !String::from_utf8_lossy(&o.stderr).contains("panicked"), "{}", String::from_utf8_lossy(&o.stderr));
    }
    let _ = child.kill();
    let _ = std::fs::remove_dir_all(&home);
    // A longest time of 90 minutes; a job GitHub says nothing of when asked; one GitHub says another runner took,
    // whose own runner GitHub says nothing of. Swept as they stand, said in minutes.
    let served = serve(|_| {});
    served.connect_github();
    served.aws.put(&format!("/superci/{PLANE}/ROUTING"), r#"{"order":[{"cloud":"cloudflare"}],"max_minutes":90}"#);
    let (long, q) = served.github.queue("long", "superci", served.now_ms()); served.webhook(q); served.webhook(served.github.start(long));
    let (untold, q) = served.github.queue("untold", "superci", served.now_ms()); served.webhook(q);
    let (taken, q) = served.github.queue("taken elsewhere", "superci", served.now_ms()); served.webhook(q);
    let _ = served.github.start_elsewhere(taken, "someone-elses-runner");
    served.github.fail("GET", &format!("/actions/jobs/{untold}"), 500, "Server Error");
    served.github.fail("GET", "/actions/runners/", 502, "Bad Gateway");
    // (And a GitLab job no runner ever takes: its runners taken back from GitLab as it is given up.)
    served.connect_gitlab();
    let (gl, p) = served.gitlab.pending("gl never taken", &["superci"], served.now_ms());
    assert!(served.gitlab_webhook(p) < 300);
    let state = |id: u64| served.store.under(&format!("job:{id}"))[0].1.clone();
    // Up a while, not yet late: kept as they are, asked again at the next sweep.
    served.later(2 * 60_000); served.upkeep();
    assert!(state(untold)["state"] == "launched" && state(taken)["state"] == "launched", "{} {}", state(untold), state(taken));
    // Late: started again, and the other ended (its job is elsewhere); the long one past its 90 minutes.
    served.later(4 * 60_000); served.upkeep();
    served.later(100 * 60_000); served.upkeep();
    for _ in 0..3 { served.later(5 * 60_000); served.upkeep(); }
    let g = served.store.under(&format!("job:gl{gl}"))[0].1.clone();
    assert!(g["state"] == "failed" && g["error"].as_str().unwrap_or_default().contains("three times"), "{g}");
    assert!(state(long)["error"].as_str().unwrap_or_default().contains("ran past its longest time (90 minutes)"), "{}", state(long));
    let home = common::home(&served);
    let (mut child, link) = dashboard(&home);
    b.goto(&format!("{link}&p=jobs"));
    b.wait(&reads("ran past its longest time (90 minutes)"));
    let _ = child.kill();
    let _ = std::fs::remove_dir_all(&home);
}


#[test]
fn cloudflare_jobs_are_measured_in_each_account_that_answers_and_what_is_no_cloudflare_container_is_left_alone() {
    let Some(mut b) = Browser::open(1300, 900) else { eprintln!("no Chrome here: skipped"); return };
    let served = serve(|_| {});
    served.connect_github();
    // Jobs that ran on Cloudflare's containers, each ended as said; their containers as Cloudflare named them.
    let mut ids = vec![];
    for (name, machine, cloud, kind, ago) in [
        ("measured", "a".repeat(64), "cloudflare", Some("4cpu-12gb"), 300_000u64),
        // (A name as long as a container's, but not one; one ended three days ago; one that ran elsewhere; one of no
        // size Cloudflare counted nothing for.)
        ("not hex", "g".repeat(64), "cloudflare", Some("4cpu-12gb"), 300_000),
        ("days ago", "b".repeat(64), "cloudflare", Some("4cpu-12gb"), 3 * 86_400_000),
        ("on aws", "c".repeat(64), "aws", Some("4cpu-12gb"), 300_000),
        ("counted nothing", "d".repeat(64), "cloudflare", None, 300_000),
    ] {
        let (id, q) = served.github.queue(name, "superci", served.now_ms()); served.webhook(q);
        served.webhook(served.github.start(id));
        served.webhook(served.github.finish(id, "success", "2026-10-15T10:00:01.0000000Z ok", served.now_ms()));
        let now = served.now_ms(); let mut m = served.store.0.lock().unwrap(); let k = format!("job:{id}"); let mut j: serde_json::Value = serde_json::from_str(&m[&k]).unwrap();
        j["machine_id"] = machine.into(); j["cloud"] = cloud.into(); j["started_ms"] = (now - ago - 60_000).into(); j["ended_ms"] = (now - ago).into();
        match kind { Some(k) => j["machine_type"] = k.into(), None => { j.as_object_mut().unwrap().remove("machine_type"); } }
        m.insert(k, j.to_string());
        ids.push((name, id));
    }
    // Signed in to Cloudflare, two accounts; the first's usage not answered (Cloudflare's fault), the second's as it said.
    let home = signed_in(&served);
    let file = home.join("workspaces/default/sign-ins.json");
    let mut kept: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(&file).unwrap()).unwrap();
    kept["cloudflare"] = serde_json::json!({ "access": "cloudflare-access-for-tests", "expires_at_ms": 4102444800000u64, "refresh": "cloudflare-refresh-for-tests" });
    std::fs::write(&file, kept.to_string()).unwrap();
    served.aws.fail("/client/v4/accounts?", 200, r#"{"result":[{"id":"1111111111111111111111111111111a","name":"Acme"},{"id":"2222222222222222222222222222222b","name":"Acme Labs"}],"success":true,"errors":[],"messages":[]}"#, None);
    served.aws.fail("/workers/scripts", 200, r#"{"result":[],"success":true,"errors":[],"messages":[]}"#, None);
    served.aws.fail("/workers/subdomain", 200, r#"{"result":{"subdomain":"acme"},"success":true,"errors":[],"messages":[]}"#, None);
    served.aws.fail("/graphql", 500, r#"{"data":null,"errors":[{"message":"Internal server error"}]}"#, Some(1));
    let sum = |id: String, mem: f64| serde_json::json!({ "dimensions": { "instanceId": id }, "sum": { "cpuTimeSec": 45.0, "allocatedMemory": mem, "allocatedDisk": 2.0e12, "txBytes": 1.0e8 } });
    served.aws.fail("/graphql", 200, &serde_json::json!({ "data": { "viewer": { "accounts": [{ "g": [sum("a".repeat(64), 1.0e12), sum("c".repeat(64), 1.0e12), sum("d".repeat(64), 0.0)] }] } }, "errors": null }).to_string(), None);
    let (mut child, link) = dashboard(&home);
    b.goto(&format!("{link}&p=overview"));
    b.wait(&shows("Usage"));
    let job = |name: &str| served.store.under(&format!("job:{}", ids.iter().find(|(n, _)| *n == name).unwrap().1))[0].1.clone();
    until("its cost settled at what the second account measured", || job("measured")["cost_from"] == "measured");
    for name in ["not hex", "days ago", "on aws", "counted nothing"] { assert!(job(name)["cost_from"] != "measured", "{name}") }
    // Both accounts asked.
    let asked = served.aws.asked.lock().unwrap().iter().filter(|a| a["url"].as_str().unwrap_or_default().contains("graphql")).map(|a| a["asked"].to_string()).collect::<Vec<_>>().join(" ");
    assert!(asked.contains("1111111111111111111111111111111a") && asked.contains("2222222222222222222222222222222b"), "{asked}");
    let _ = child.kill();
    let _ = std::fs::remove_dir_all(&home);
}

