        served.store.0.lock().unwrap().insert(format!("cache:gh123:refs/heads/main:v1:{key}"), serde_json::json!({ "id": key, "region": "us-east-1", "size": 1_000_000, "made": served.now_ms() - 3_600_000, "done": true }).to_string());
