#[test]
fn finding_control_planes_with_awss_sign_in_over_or_the_only_cloud_not_answering_says_so() {
    let Some(mut b) = Browser::open(1300, 900) else { eprintln!("no Chrome here: skipped"); return };
    let served = serve(|_| {});
    let home = common::home(&served);
    let file = home.join("workspaces/default/sign-ins.json");
    let mut kept: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(&file).unwrap()).unwrap();
    kept["plane"] = serde_json::Value::Null;
    kept["aws"] = serde_json::json!({ "region": "us-east-1", "account_id": "111111111111", "who": "arn:aws:sts::111111111111:assumed-role/Admin/someone",
        "creds": { "access_key_id": "ASIAEXAMPLE", "secret_access_key": "example", "session_token": "example", "expires_at_ms": 1 }, "refresh_token": "", "dpop": { "private_b64": "", "kid": "" } });
    std::fs::write(&file, kept.to_string()).unwrap();
    std::fs::write(home.join("aws-at"), &served.aws.url).unwrap();
    let pages = |b: &mut Browser, link: &str| for p in ["overview", "planes", "plane"] { b.goto(&format!("{link}&p={p}")); b.wait("document.querySelector('main') !== null"); };
    let (mut child, link) = dashboard(&home);
    pages(&mut b, &link);
    let _ = child.kill();
    // Only Cloudflare, and it answers nothing.
    let mut kept: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(&file).unwrap()).unwrap();
    kept["aws"] = serde_json::Value::Null;
    kept["cloudflare"] = serde_json::json!({ "access": "cloudflare-access-for-tests", "expires_at_ms": 4102444800000u64, "refresh": "cloudflare-refresh-for-tests" });
    std::fs::write(&file, kept.to_string()).unwrap();
    served.aws.fail("api.cloudflare.com", 503, "upstream connect error", None);
    let (mut child, link) = dashboard(&home);
    pages(&mut b, &link);
    let page = b.eval("document.body.innerText").as_str().unwrap_or_default().to_string();
    assert!(!page.contains("panicked"), "{page}");
    served.aws.fail_none();
    let _ = child.kill();
    let _ = std::fs::remove_dir_all(&home);
}

/// A workspace whose control plane does not take this computer's key: its Settings still has what is this
/// computer's own (its id, removing it when there are others), under the card that says why, and it is removed.
#[test]
fn a_workspace_whose_control_plane_refuses_the_key_can_still_be_removed_from_settings() {
    let Some(mut b) = Browser::open(1300, 900) else { eprintln!("no Chrome here: skipped"); return };
    let served = serve(|_| {});
    *served.aws.old_version.lock().unwrap() = Some("0.19.12".into());
    let home = home(&served);
    let other = home.join("workspaces/other");
    std::fs::create_dir_all(&other).unwrap();
    std::fs::copy(home.join("workspaces/default/sign-ins.json"), other.join("sign-ins.json")).unwrap();
    let (mut child, link) = common::dashboard_with(&home, &[("SUPERCI_KEY_WAIT_S", "1")]);
    b.goto(&link);
    b.wait("document.querySelector('main') !== null");
    b.goto(&format!("{link}&p=settings"));
    b.wait(&format!("{} && {}", shows("does not take this computer's key"), shows("Remove this workspace")));
    b.click("main button", "Remove");
    b.wait("document.getElementById('remove-workspace').open");
    b.click("#remove-workspace button", "Remove from this computer");
    until("the workspace forgotten here", || !home.join("workspaces/default").exists());
    assert!(other.exists(), "the other one kept");
    let _ = child.kill();
    let _ = std::fs::remove_dir_all(&home);
}

/// What the dashboard sends a control plane that it should never take: costs that are no cost (negative, too large,
/// not a number), for what is no job, for a job not on Cloudflare or still running; a job's log asked by an id that
/// is none, or of a GitLab that is no name. Each left alone, the job's page as it was.
#[test]
fn costs_and_logs_asked_of_a_control_plane_with_what_is_no_job_are_left_alone() {
    let Some(mut b) = Browser::open(1300, 900) else { eprintln!("no Chrome here: skipped"); return };
    let served = serve(|_| {});
    served.connect_github();
    let (done, q) = served.github.queue("ended", "superci", served.now_ms()); served.webhook(q);
    served.webhook(served.github.start(done));
    served.webhook(served.github.finish(done, "success", "2026-10-15T10:00:01.0000000Z ok", served.now_ms()));
    let (running, q) = served.github.queue("running", "superci", served.now_ms()); served.webhook(q);
    served.webhook(served.github.start(running));
    // (The ended one as if it ran on AWS: not Cloudflare's to measure.)
    let agent = ureq::Agent::config_builder().http_status_as_error(false).build().new_agent();
    let post = |body: serde_json::Value| -> serde_json::Value { agent.post(&format!("{}/costs", served.url)).header("authorization", &format!("Bearer {}", served.key)).send(body.to_string()).map(|mut r| r.body_mut().read_json().unwrap_or_default()).unwrap_or_default() };
    for bad in [serde_json::json!(-1.0), serde_json::json!(5000.0), serde_json::json!("x")] {
        assert_eq!(post(serde_json::json!({ "measured": { format!("job:{done}"): bad } }))["kept"], 0, "{bad}");
    }
    let said = post(serde_json::json!({ "measured": { format!("job:{running}"): 0.5, "run:1": 0.5, "job:999": 0.5 } }));
    assert_eq!(said["kept"], 0, "a job still running, no job, one not kept: {said}");
    assert_eq!(post(serde_json::json!({ "measured": { format!("job:{done}"): 0.5 } }))["kept"], 1, "the ended Cloudflare job");
    {
        let mut store = served.store.0.lock().unwrap();
        let k = format!("job:{done}");
        let mut j: serde_json::Value = serde_json::from_str(&store[&k]).unwrap();
        j["cloud"] = "aws".into();
        store.insert(k, j.to_string());
    }
    assert_eq!(post(serde_json::json!({ "measured": { format!("job:{done}"): 0.5 } }))["kept"], 0, "not Cloudflare's");
    for path in ["/job/log?id=abc", "/job/log?id=", "/job/log?id=1&gl=Not%20a%20name", "/job/log?id=1&gl=", &format!("/job/log?id={done}&steps=1")] {
        let status = agent.get(&format!("{}{path}", served.url)).header("authorization", &format!("Bearer {}", served.key)).call().map(|r| r.status().as_u16()).unwrap_or(0);
        assert!(status < 500, "{path}: {status}");
    }
    let home = signed_in(&served);
    let (mut child, link) = dashboard(&home);
    b.goto(&format!("{link}&p=job&id={done}"));
    b.wait(&format!("{} && !document.querySelector('main').innerText.includes('Reading your control plane')", shows("Status")));
    let _ = child.kill();
    let _ = std::fs::remove_dir_all(&home);
}

/// Starting a job's machine when AWS answers slowly (each pool's answer taking seconds, until the time a start may
/// take is over: the job waits for the next sweep), while the job itself ends (cancelled meanwhile: no machine kept
/// for it), and when GitHub says the runner's name is taken. Each job's page says what happened.
#[test]
fn a_machine_start_out_of_time_ended_meanwhile_or_with_its_runner_name_taken_is_said_on_the_jobs_page() {
    let Some(mut b) = Browser::open(1300, 900) else { eprintln!("no Chrome here: skipped"); return };
    let served = serve(|c| {
        (c.aws_own, c.aws_own_creds) = (Some(("111111111111".into(), "us-east-1".into())), Some(superci_core::aws::Credentials { access_key_id: "ASIAX".into(), secret_access_key: "secret".into(), session_token: Some("tok".into()), expires_at_ms: u64::MAX }));
    });
    served.connect_github();
    *served.public.lock().unwrap() = Some("https://plane.acme.test".into());
    served.aws.put(&format!("/superci/{PLANE}/ROUTING"), r#"{"order":[{"cloud":"aws","max_jobs":100},{"cloud":"aws-on-demand"},{"cloud":"cloudflare","off":true}]}"#);
    served.aws.replaying(include_str!("../fixtures/aws/launch/spot.jsonl"), &[]);
    let no_room = superci_testkit::ec2_error("InsufficientInstanceCapacity", "We currently do not have sufficient capacity in the Availability Zone you requested.");
    let mut ids = vec![];
    // Out of time: every pool's answer six seconds on, none with room.
    served.store.0.lock().unwrap().insert("aws:no-fleet".into(), served.now_ms().to_string());
    let tick = served.ticker();
    served.aws.during("RunInstances", move || tick(6_000));
    served.aws.fail("RunInstances", 500, &no_room, None);
    let (id, q) = served.github.queue("slow", "superci/spot=false", served.now_ms());
    assert!(served.webhook(q) < 300);
    ids.push(id);
    served.aws.during.lock().unwrap().clear();
    served.aws.fail_none();
    // Ended while its machine was asked for: the job's record says it ended before AWS answered.
    let store = served.store.0.clone();
    served.aws.during("RunInstances", move || {
        let mut s = store.lock().unwrap();
        let keys: Vec<String> = s.keys().filter(|k| k.starts_with("job:")).cloned().collect();
        for k in keys {
            let mut j: serde_json::Value = serde_json::from_str(&s[&k]).unwrap();
            if ["ends meanwhile", "ends as it starts"].contains(&j["name"].as_str().unwrap_or_default()) && j["ended_ms"].is_null() {
                j["state"] = "done".into(); j["ended_ms"] = j["at_ms"].clone(); j["rev"] = (j["rev"].as_u64().unwrap_or(0) + 1).into(); s.insert(k, j.to_string());
            }
        }
    });
    // (AWS failing it, Cloudflare next in the order: its record is read again before Cloudflare is asked.)
    served.aws.put(&format!("/superci/{PLANE}/ROUTING"), r#"{"order":[{"cloud":"aws","max_jobs":100},{"cloud":"cloudflare"}]}"#);
    served.aws.fail("RunInstances", 500, &superci_testkit::ec2_error("InternalError", "An internal error has occurred"), None);
    let (id, q) = served.github.queue("ends meanwhile", "superci", served.now_ms());
    assert!(served.webhook(q) < 300);
    ids.push(id);
    served.aws.fail_none();
    served.aws.put(&format!("/superci/{PLANE}/ROUTING"), r#"{"order":[{"cloud":"aws","max_jobs":100},{"cloud":"aws-on-demand"},{"cloud":"cloudflare","off":true}]}"#);
    // And one that ends as its machine starts: the machine ended at once, its runner taken back.
    let started: String = include_str!("../fixtures/aws/launch/on-demand.jsonl").lines().filter_map(|l| serde_json::from_str::<serde_json::Value>(l).ok())
        .find(|v| v["asked"].as_str().unwrap_or_default().contains("Action=RunInstances") && v["status"] == 200).map(|v| v["answer"].as_str().unwrap_or_default().to_string()).unwrap();
    served.aws.fail("RunInstances", 200, &started, None);
    let (as_it_starts, q) = served.github.queue("ends as it starts", "superci", served.now_ms());
    assert!(served.webhook(q) < 300);
    served.aws.during.lock().unwrap().clear();
    // GitHub failing the runner's registration otherwise: tried again later.
    served.github.fail("POST", "generate-jitconfig", 500, "Server Error");
    let (id, q) = served.github.queue("registration failed", "superci", served.now_ms());
    assert!(served.webhook(q) < 500);
    ids.push(id);
    served.github.fail_none();
    // The runner's name taken at GitHub.
    served.github.fail("POST", "generate-jitconfig", 409, "Already exists - A runner with the name acmeci-1 already exists.");
    let (id, q) = served.github.queue("name taken", "superci", served.now_ms());
    assert!(served.webhook(q) < 500);
    ids.push(id);
    served.github.fail_none();
    served.aws.fail_none();
    let state = |id: u64| served.store.under(&format!("job:{id}"))[0].1.clone();
    assert!(state(ids[0])["error"].as_str().unwrap_or_default().contains("out of time") || state(ids[0])["asks"].as_array().is_some_and(|a| a.len() > 1), "{}", state(ids[0]));
    assert!(state(ids[1])["machine_id"].is_null() && state(ids[1])["cloud"] != "cloudflare", "{}", state(ids[1]));
    assert!(state(ids[2])["error"].as_str().unwrap_or_default().contains("500") && state(ids[3])["runner_suffix"].is_string(), "{} {}", state(ids[2]), state(ids[3]));
    assert!(state(as_it_starts)["state"] == "done" && served.aws.asked.lock().unwrap().iter().any(|a| a["asked"].as_str().unwrap_or_default().contains("Action=TerminateInstances")), "{}", state(as_it_starts));
    // A sweep on: the slow one asked again.
    served.later(70_000);
    served.upkeep();
    let home = signed_in(&served);
    let (mut child, link) = dashboard(&home);
    for id in ids {
        b.goto(&format!("{link}&p=job&id={id}"));
        b.wait(&format!("{} && !document.querySelector('main').innerText.includes('Reading your control plane')", shows("Status")));
    }
    let _ = child.kill();
    let _ = std::fs::remove_dir_all(&home);
}

/// What Modal says beside its answers (a client release it will stop taking): to the dashboard's own calls, or to the
/// control plane's launchers as it kept it, a line above every page with the way on, once each.
#[test]
fn what_modal_says_beside_its_answers_is_a_line_above_the_pages() {
    // To the dashboard itself, looking in Modal too (its workspace as Modal answered).
    let served = serve(|_| {});
    let home = signed_in(&served);
    let file = home.join("workspaces/default/sign-ins.json");
    let mut k: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(&file).unwrap()).unwrap();
    k["modal"] = serde_json::json!({ "token_id": "ak-modal-for-tests", "token_secret": "as-modal-for-tests", "workspace": "acmeorg" });
    std::fs::write(&file, k.to_string()).unwrap();
    served.aws.replaying(include_str!("../fixtures/modal/01-look.jsonl"), &[]);
    *served.aws.modal_warning.lock().unwrap() = Some("modal-go%200.11%20is%20deprecated%2C%20upgrade%20by%202027-01-01".into());
    let (mut child, link) = dashboard(&home);
    let page = || common::part(&link, "/?p=overview&fragment=1").1;
    until("Modal's word", || common::words(&page()).contains("Modal says: “modal-go 0.11 is deprecated, upgrade by 2027-01-01” A newer SuperCI answers it"));
    // And the control plane's launcher's, as the control plane kept it; each once.
    served.store.0.lock().unwrap().insert("cloud:says".into(), serde_json::json!([{ "cloud": "modal", "said": "modal 1.6 is deprecated" }, { "cloud": "modal", "said": "modal-go 0.11 is deprecated, upgrade by 2027-01-01" }]).to_string());
    until("the control plane's word", || page().contains("Modal says: “modal 1.6 is deprecated”"));
    let page = page();
    assert!(page.matches("modal-go 0.11 is deprecated").count() == 1 && page.contains(r#"href="/?p=planes">Control plane</a>"#), "{}", common::words(&page));
    let _ = child.kill();
    let _ = std::fs::remove_dir_all(&home);
}

/// A change a teammate makes on another computer, through the control plane (as their dashboard makes it).
fn teammate_changes(served: &superci_testkit::Served, changes: serde_json::Value) {
    let agent: ureq::Agent = ureq::Agent::config_builder().http_status_as_error(false).build().into();
    let r = agent.post(&format!("{}/settings", served.url)).header("authorization", &format!("Bearer {}", served.key)).send(serde_json::json!({ "changes": changes }).to_string()).unwrap();
    assert_eq!(r.status(), 200);
}

/// A provider's dialog left open while a teammate changes one of its fields on another computer: saved with another of
/// its fields changed, the teammate's change stays; saved with that same field changed, refused, saying what it is now.
#[test]
fn a_dialog_saved_after_a_teammate_changed_one_of_its_fields_keeps_theirs_or_says_it_changed() {
    let Some(mut b) = Browser::open(1300, 900) else { eprintln!("no Chrome here: skipped"); return };
    let served = serve(|_| {});
    served.aws.put(&format!("/superci/{PLANE}/ROUTING"), r#"{"order":[{"cloud":"cloudflare","max_jobs":3}]}"#);
    let home = signed_in(&served);
    let (mut child, link) = common::dashboard_with(&home, &[("SUPERCI_VIEWS_S", "0")]);
    let pool = || served.aws.settings(PLANE).into_iter().find(|(k, _)| k == "ROUTING").and_then(|(_, r)| serde_json::from_str::<serde_json::Value>(&r).ok()).map(|r| r["order"][0].clone()).unwrap_or_default();
    let open = |b: &mut Browser| {
        b.goto(&format!("{link}&p=runners"));
        b.wait(r#"document.querySelector('button[aria-label="Cloudflare settings"]') !== null && !document.body.classList.contains('busy')"#);
        b.click(r#"button[aria-label="Cloudflare settings"]"#, "");
        b.wait("document.getElementById('pool-0').open");
    };
    // Its budget set while the teammate made it 7 at once: theirs stays, the budget is taken.
    open(&mut b);
    assert_eq!(b.eval("document.querySelector('#pool-0 input[name=max]').value"), serde_json::json!("3"));
    teammate_changes(&served, serde_json::json!([{ "op": "set", "path": ["routing", "order", "cloudflare", "max_jobs"], "value": 7 }]));
    b.fill("#pool-0 input[name=usd]", "30");
    b.click("#pool-0 button.primary", "Save");
    until("the budget", || pool()["monthly_usd"] == 30.0);
    assert_eq!(pool()["max_jobs"], 7, "{}", pool());
    // Jobs at once set by both: refused, saying the teammate's.
    open(&mut b);
    teammate_changes(&served, serde_json::json!([{ "op": "set", "path": ["routing", "order", "cloudflare", "max_jobs"], "value": 9 }]));
    b.fill("#pool-0 input[name=max]", "5");
    b.click("#pool-0 button.primary", "Save");
    b.wait(&page_shows("Changed on another computer meanwhile"));
    assert!(b.eval("document.body.innerText").as_str().unwrap().contains("Cloudflare's jobs at once is 9 now"));
    assert_eq!(pool()["max_jobs"], 9);
    let _ = child.kill();
    let _ = std::fs::remove_dir_all(&home);
}
